83	  (globalThis as any).formatDate     = (_d: string) => '—';
84	  (globalThis as any).Router         = { _setPolling: vi.fn() };
85	
86	  // Provide a localStorage stub visible to vm.runInThisContext (see JSDoc above).
87	  (global as any).localStorage = makeLocalStorageStub();
88	
89	  // Load scripts in dependency order: utils first (defines escapeHtml, ProjectNameCache,
